import {session} from './auth.js';
import {loadCloud,nativePreview,browserRead} from './ingestion-client.js';
import {openImporter} from './data-page.js';
import * as repository from './project-repository.js';
import {mountWorkspaceMap} from './project-map.js';

let host,activeProject,selected='',search='',basemap='grid',inspector=true,labels=true,showWells=true,showDeviation=true,zoom=1,paths=[],pathIssues=[],loading=false,loadedAt=0,loadedSignature='',resizeObserver,mapGeneration=0,googleMap;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=s=>document.querySelector(s);
const isWgs84=value=>/^(?:EPSG:)?4326$|^WGS\s?84$/i.test(String(value||'').trim());
const validPoint=p=>p&&typeof p.lat==='number'&&typeof p.lng==='number'&&Number.isFinite(p.lat)&&Number.isFinite(p.lng)&&Math.abs(p.lat)<=85&&Math.abs(p.lng)<=180;
const projection=p=>[6378137*p.lng*Math.PI/180,6378137*Math.log(Math.tan(Math.PI/4+p.lat*Math.PI/360))];
export function configureMapWorkspace(value){host=value;}
function settings(){return host.getState().mapWorkspace||{locations:{},symbols:{}};}
function datasets(){return (host.getState().ingestion?.datasets||[]).filter(d=>d.active!==false);}
function wells(){return [...new Set([...(host.getState().wellDrafts||[]).map(w=>w.id),...datasets().map(d=>d.well)].filter(Boolean))];}
function located(){return wells().flatMap(id=>{const p=settings().locations?.[id];return p?.confirmed&&validPoint(p)?[{id,...p}]:[];});}
function saveSetting(key,value){const state=host.getState();state.mapWorkspace||={locations:{},symbols:{}};state.mapWorkspace[key]=value;host.save();}
const menu=(title,items)=>`<details class="mw-menu"><summary>${title} <span aria-hidden="true">⌄</span></summary><div>${items.map(([id,label,disabled])=>`<button type="button" data-map-command="${id}" ${disabled?'disabled':''}>${label}</button>`).join('')}</div></details>`;
export function mapWorkspaceView(){
 const project=host.getProject(),scope=session.user?.uid+':'+project.id;if(activeProject!==scope){activeProject=scope;selected='';search='';paths=[];pathIssues=[];loadedAt=0;loadedSignature='';loading=false;basemap='grid';zoom=1;inspector=true;}
 const ids=wells();if(!ids.includes(selected))selected=ids[0]||'';const p=located().find(w=>w.id===selected),deviations=datasets().filter(d=>d.family==='deviation'&&d.well===selected);
 return `<section class="map-workspace ${inspector?'':'inspector-collapsed'}"><header class="mw-heading"><div><div class="study-kicker">SPATIAL WORKSPACE</div><h1>Project map</h1><p>${esc(project.name)} · ${located().length}/${ids.length} wells located</p></div><div class="actions"><button data-map-command="fit">Fit project</button><button id="mw-inspector-toggle" aria-expanded="${inspector}" aria-controls="mw-inspector">${inspector?'Hide':'Show'} inspector</button></div></header><div class="mw-ribbon" aria-label="Map ribbon">${menu('＋ Add',[['well','Well locations…'],['deviation','Deviation data for selected well…',!selected],['spatial','Spatial data…'],['seismic','Seismic data…',!project.workflows?.includes('seismic')]])}${menu('Basemap',[['grid','Field grid'],['roadmap','Google Roadmap'],['satellite','Google Satellite'],['hybrid','Google Hybrid'],['terrain','Google Terrain']])}${menu('View',[['fit','Fit all evidence'],['labels','Show / hide well labels'],['wells','Show / hide wells'],['trajectories','Show / hide deviation'],['inspector','Show / hide inspector']])}${menu('Style',[['style','Selected well symbol…',!selected]])}${menu('Export',[['export','Field map (SVG)',basemap!=='grid']])}<span class="mw-ribbon-status">${loading?'Loading evidence…':'Project evidence'}</span></div><div class="mw-body"><aside class="mw-contents"><div class="mw-panel-title">Contents <button data-map-command="refresh" aria-label="Refresh map evidence">↻</button></div><label class="mw-search">${host.icon('search')}<input id="mw-search" aria-label="Find a well" placeholder="Find a well…" value="${esc(search)}"></label><h3>BASEMAP</h3><div class="mw-basemap">${basemap==='grid'?'Field grid · EPSG:3857':'Google '+basemap}</div><h3>PROJECT LAYERS</h3><label class="mw-layer"><input id="mw-wells" type="checkbox" ${showWells?'checked':''}>Wells <span>${ids.length}</span></label><label class="mw-layer"><input id="mw-deviation" type="checkbox" ${showDeviation?'checked':''}>Deviation trajectories <span>${paths.length}</span></label><h3>WELLS</h3><div class="mw-well-list">${ids.length?ids.map(id=>`<button data-map-well="${esc(id)}" aria-pressed="${id===selected}" ${id.toLowerCase().includes(search.toLowerCase())?'':'hidden'}><span class="mw-well-dot"></span><span><strong>${esc(id)}</strong><small>${located().some(p=>p.id===id)?'Confirmed location':'Location needs review'}</small></span></button>`).join(''):'<p class="sub">No wells registered. Add well data to begin.</p>'}</div><p class="mw-reference-note">Only confirmed locations and supplied, referenced deviation coordinates are plotted.</p></aside><div class="mw-map-column"><div class="mw-canvas" id="mw-canvas"><div class="mw-map-label">${basemap==='grid'?'FIELD GRID · EPSG:3857':'GOOGLE '+basemap.toUpperCase()}</div><div class="mw-north" aria-label="North">↑<small>N</small></div><div id="mw-renderer" aria-label="Project map"></div><div id="mw-map-feedback" role="status"></div><div class="mw-map-controls"><button data-map-command="zoom-in" aria-label="Zoom in">＋</button><button data-map-command="zoom-out" aria-label="Zoom out">−</button><button data-map-command="fit" aria-label="Fit evidence">⌖</button></div></div><div class="mw-legend"><span><i class="mw-dot"></i>Wellhead</span><span><i class="mw-line"></i>Deviation trajectory</span><span><i class="mw-end"></i>Survey end</span></div></div><aside class="mw-inspector" id="mw-inspector" ${inspector?'':'hidden'}><div class="mw-panel-title">Inspector<button id="mw-inspector-close" aria-label="Collapse inspector">×</button></div>${selected?`<h2>${esc(selected)}</h2><p class="sub">Surface well</p><dl><dt>Location reference</dt><dd>${p?'WGS84 · user confirmed':'Unconfirmed — not plotted'}</dd>${p?`<dt>Latitude / longitude</dt><dd class="mw-coordinates">${p.lat.toFixed(6)}, ${p.lng.toFixed(6)}</dd>`:''}<dt>Deviation evidence</dt><dd>${deviations.length} imported ${deviations.length===1?'dataset':'datasets'}</dd></dl><div class="mw-inspector-actions"><button data-map-command="location">${p?'Edit':'Review'} well location</button><button data-map-command="deviation" class="primary">＋ Add deviation data</button><button data-map-command="evidence">View well evidence</button></div><div class="mw-style"><h3>APPEARANCE</h3><label class="field">Well symbol<select id="mw-symbol">${['Wellhead','Circle','Square'].map(s=>`<option ${settings().symbols?.[selected]===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="mw-layer"><input id="mw-labels" type="checkbox" ${labels?'checked':''}>Show well names</label></div>`:'<div class="mw-inspector-empty">Select a well to inspect its location and add deviation evidence.</div>'}<div class="mw-path-issues">${pathIssues.map(i=>`<p>${esc(i)}</p>`).join('')}</div></aside></div><footer class="mw-status"><span>${located().length} located wells · ${paths.length} mapped deviation ${paths.length===1?'survey':'surveys'}</span><span>Source positions: WGS84 · Field grid: Web Mercator E/N (km)</span></footer></section>`;
}
export function bindMapWorkspace(){
 if(!$('#mw-canvas'))return;const project=host.getProject();
 const toggle=()=>{inspector=!inspector;draw();};$('#mw-inspector-toggle').onclick=toggle;$('#mw-inspector-close')?.addEventListener('click',toggle);
 document.querySelectorAll('[data-map-well]').forEach(b=>b.onclick=()=>{selected=b.dataset.mapWell;inspector=true;draw();});
 $('#mw-search').oninput=e=>{search=e.target.value;document.querySelectorAll('[data-map-well]').forEach(b=>b.hidden=!b.dataset.mapWell.toLowerCase().includes(search.toLowerCase()));};
 $('#mw-wells').onchange=e=>{showWells=e.target.checked;renderMap();};$('#mw-deviation').onchange=e=>{showDeviation=e.target.checked;renderMap();};$('#mw-labels')?.addEventListener('change',e=>{labels=e.target.checked;renderMap();});
 $('#mw-symbol')?.addEventListener('change',e=>{saveSetting('symbols',{...settings().symbols,[selected]:e.target.value});renderMap();});
 document.querySelectorAll('[data-map-command]').forEach(b=>b.onclick=()=>{b.closest('details')?.removeAttribute('open');command(b.dataset.mapCommand);});
 const menus=[...document.querySelectorAll('.mw-menu')];menus.forEach(m=>m.ontoggle=()=>{if(m.open)menus.filter(n=>n!==m).forEach(n=>n.open=false);});
 renderMap();const signature=datasets().map(d=>d.id+JSON.stringify(d.references||{})).join('|');if(signature!==loadedSignature&&!loading)refresh();else if(project.storage==='cloud'&&Date.now()-loadedAt>30000&&!loading)refresh();else if(!loadedAt&&!loading)refresh();
}
function draw(){host.render();}
async function command(action){try{
 if(action==='inspector'){inspector=!inspector;draw();return;}
 if(action==='deviation'){if(!selected){host.toast('Select a well before adding deviation data.');return;}await openImporter({family:'deviation',well:selected});return;}
 if(['well','spatial','seismic'].includes(action)){await openImporter({family:{well:'well_headers',spatial:'spatial',seismic:'seismic'}[action]});return;}
 if(action==='location'){await editLocation();return;}
 if(action==='evidence'){host.navigate('files');return;}
 if(action==='refresh'){await refresh();return;}
 if(action==='labels'){labels=!labels;draw();return;}if(action==='wells'){showWells=!showWells;draw();return;}if(action==='trajectories'){showDeviation=!showDeviation;draw();return;}
 if(action==='style'){inspector=true;draw();$('#mw-symbol')?.focus();return;}
 if(['grid','roadmap','satellite','hybrid','terrain'].includes(action)){basemap=action;draw();return;}
 if(action==='fit'){zoom=1;renderMap();return;}if(action==='zoom-in'||action==='zoom-out'){if(basemap!=='grid'&&googleMap){googleMap.setZoom(googleMap.getZoom()+(action==='zoom-in'?1:-1));return;}zoom=Math.max(.2,Math.min(30,zoom*(action==='zoom-in'?1.4:1/1.4)));renderMap();return;}
 if(action==='export'){const svg=$('#mw-renderer svg');if(!svg){host.toast('Select Field grid to export the map.');return;}const copy=svg.cloneNode(true);copy.setAttribute('xmlns','http://www.w3.org/2000/svg');const style=document.createElementNS('http://www.w3.org/2000/svg','style');style.textContent='text{font:11px sans-serif;fill:#264b42}.mw-gridline{stroke:#dce6e1;stroke-width:1}.mw-trajectory{stroke:#b47c51;stroke-width:2;fill:none}.mw-point{fill:#fff;stroke:#087c73;stroke-width:1.5}';copy.prepend(style);host.download(host.getProject().name+'-map.svg',new Blob([new XMLSerializer().serializeToString(copy)],{type:'image/svg+xml'}));}
 }catch(error){host.toast(error.message);}}
async function refresh(){
 const project=host.getProject(),id=project.id,uid=session.user?.uid;loading=true;try{await host.flush();if(project.storage==='cloud'){const data=await loadCloud(project);if(host.getProject()?.id!==id||session.user?.uid!==uid)return;host.getState().ingestion=data;}await readDeviations(project);if(host.getProject()?.id!==id||session.user?.uid!==uid)return;loadedSignature=datasets().map(d=>d.id+JSON.stringify(d.references||{})).join('|');loadedAt=Date.now();}catch(error){if(activeProject===uid+':'+id)host.toast(error.message);}finally{if(activeProject===uid+':'+id){loading=false;if($('#mw-canvas'))draw();}}
}
async function readDeviations(project){
 const result=[],issues=[],uid=session.user?.uid;
 for(const d of datasets().filter(d=>d.family==='deviation')){
  const mapping=d.mapping||{},refs=d.references||{};if(d.issues?.some(i=>i.severity==='blocking')){issues.push(`${d.well||d.name}: resolve import validation before map use.`);continue;}
  if(!d.well){issues.push(`${d.name}: assign this survey to a well.`);continue;}
  if(!isWgs84(refs.crs)||!['Longitude / latitude','Latitude / longitude'].includes(refs.coordinateOrder)||mapping.x==null||mapping.y==null||mapping.x===''||mapping.y===''){issues.push(`${d.well}: deviation retained. Map display needs supplied longitude/latitude columns with confirmed WGS84 and coordinate order. MD/inclination/azimuth trajectory calculation is not available.`);continue;}
  const xi=Number(mapping.x),yi=Number(mapping.y);if(d.activeColumns&&(!d.activeColumns.includes('column-'+xi)||!d.activeColumns.includes('column-'+yi))){issues.push(`${d.well}: the coordinate columns are not active.`);continue;}
  try{const points=[];const append=text=>{for(const line of text.split('\n'))if(line.trim()){const row=JSON.parse(line),lat=refs.coordinateOrder==='Latitude / longitude'?row[xi]:row[yi],lng=refs.coordinateOrder==='Latitude / longitude'?row[yi]:row[xi];const p={lat,lng};if(!validPoint(p))throw new Error('A coordinate is missing or outside map limits; the trajectory was not plotted.');points.push(p);if(points.length>50000)throw new Error('This map supports up to 50,000 supplied stations per survey. Retain the original and export a smaller survey.');}};
   if(project.storage!=='cloud'&&d.chunks?.length){for(const chunk of d.chunks){let blob=await repository.getArtifact(project,d.importId,chunk.name);if(chunk.name.endsWith('.gz'))blob=new Blob([await new Response(blob.stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer()]);append(await blob.text());}}
   else{const source=host.getState().files?.find(f=>f.id===d.sourceId);if(!source)throw new Error('Original survey file is missing.');if(source.size>32*1024**2)throw new Error('Retained survey is too large for this map reader. Export a coordinate table smaller than 32 MiB.');const blob=await repository.source(project,source);const record=host.getState().ingestion?.imports?.find(r=>r.id===d.importId);const parsed=await browserRead(new File([blob],source.name),'deviation',{...record?.options,mapping,references:refs},{previewOnly:false,onChunk:async c=>append(await c.blob.text())});if(parsed.datasets.some(p=>p.issues.some(i=>i.severity==='blocking')))throw new Error('The retained survey has unresolved mapping or range errors.');}
   if(points.length<2)throw new Error('At least two supplied stations are required.');result.push({id:d.id,well:d.well,name:d.name,points});
  }catch(error){issues.push(`${d.well}: ${error.message}`);}
 }
 if(host.getProject()?.id===project.id&&session.user?.uid===uid){paths=result;pathIssues=issues;}
}
async function editLocation(){
 if(!selected)return;const owner=session.user?.uid,projectId=host.getProject().id,well=selected,previous=settings().locations?.[well];let suggestion=previous||{};
 if(!previous){const d=datasets().find(d=>d.well===well&&d.family==='logs');if(d){try{const details=host.getProject().storage==='cloud'?await nativePreview(host.getProject(),d.importId,d.id):d;const headers=details.metadata?.headers||{};const lat=headers.LAT?.value??headers.LATI?.value,lng=headers.LONG?.value??headers.LON?.value??headers.LONI?.value??headers.LONGITUDE?.value;if(lat!==undefined&&lng!==undefined)suggestion={lat:Number(lat),lng:Number(lng)};}catch(error){host.toast(error.message);}}}
 if(session.user?.uid!==owner||host.getProject()?.id!==projectId)return;
 host.modal('Review well location',`<h3>${esc(well)}</h3><p class="sub">Header values are suggestions. Confirm the source datum before using them. Original source data remains unchanged.</p><form id="mw-location-form"><div class="form-grid"><label class="field">Latitude<input name="lat" type="number" step="any" min="-85" max="85" required value="${Number.isFinite(suggestion.lat)?suggestion.lat:''}"></label><label class="field">Longitude<input name="lng" type="number" step="any" min="-180" max="180" required value="${Number.isFinite(suggestion.lng)?suggestion.lng:''}"></label></div><label class="layer"><input name="confirmed" type="checkbox" required>I have confirmed these coordinates use WGS84 (EPSG:4326).</label><p class="sub">Projected X/Y coordinates need conversion using their known source CRS; do not enter them as latitude/longitude.</p><p id="mw-location-error" role="alert"></p><button class="primary" type="submit">Save confirmed location</button></form>`);
 $('#mw-location-form').onsubmit=async e=>{e.preventDefault();if(session.user?.uid!==owner||host.getProject()?.id!==projectId){host.toast('This project is no longer active.');$('#dialog').close();return;}const form=e.currentTarget,fields=new FormData(form),point={lat:Number(fields.get('lat')),lng:Number(fields.get('lng')),confirmed:true,crs:'EPSG:4326',confirmedAt:new Date().toISOString()};if(!validPoint(point)||!fields.get('confirmed')){$('#mw-location-error').textContent='Enter valid WGS84 coordinates and confirm their reference.';return;}const button=form.querySelector('button');button.disabled=true;try{saveSetting('locations',{...settings().locations,[well]:point});await host.flush();$('#dialog').close();draw();}catch(error){$('#mw-location-error').textContent=error.message;button.disabled=false;}};
}
function renderMap(){
 resizeObserver?.disconnect();const element=$('#mw-renderer');if(!element)return;const generation=++mapGeneration;googleMap=null;
 const points=showWells?located():[],lines=showDeviation?paths:[],site=host.getProject().coordinates;
 if(basemap!=='grid'){element.innerHTML='';mountWorkspaceMap(element,{points,paths:lines,site,basemap,labels,symbols:settings().symbols||{},select:id=>{selected=id;inspector=true;draw();}}).then(map=>{if(generation===mapGeneration)googleMap=map;}).catch(error=>{if(generation===mapGeneration&&element.isConnected)element.textContent=error.message+' Field grid remains available.';});return;}
 const drawGrid=()=>{if(!element.isConnected)return;const width=Math.max(250,element.clientWidth),height=Math.max(360,element.clientHeight);const positions=[...points,...lines.flatMap(p=>p.points),...(validPoint(site)?[site]:[])];const feedback=$('#mw-map-feedback');if(feedback)feedback.textContent=!positions.length?(wells().length?'Review well locations to place your wells. No coordinates have been assumed.':'Add a site location or well data to begin.') : '';
  const xy=positions.map(projection),xs=xy.map(p=>p[0]),ys=xy.map(p=>p[1]);let cx=xy.length?(Math.min(...xs)+Math.max(...xs))/2:0,cy=xy.length?(Math.min(...ys)+Math.max(...ys))/2:0;const span=Math.max(xy.length?Math.max(...xs)-Math.min(...xs):0,xy.length?(Math.max(...ys)-Math.min(...ys))*width/height:0,1000)*1.4/zoom,vertical=span*height/width;const px=p=>{const [x,y]=projection(p);return [width/2+(x-cx)/span*(width-90),height/2-(y-cy)/vertical*(height-90)];};
  let grid='';for(let i=1;i<=4;i++){const x=45+(width-90)*i/5,y=45+(height-90)*i/5;grid+=`<path class="mw-gridline" d="M${x} 35V${height-35}M35 ${y}H${width-35}"/>`;if(positions.length)grid+=`<text x="${x}" y="${height-15}" text-anchor="middle">${((cx-span/2+span*i/5)/1000).toFixed(2)}</text><text x="5" y="${y-5}">${((cy+vertical/2-vertical*i/5)/1000).toFixed(2)}</text>`;}
  let geometry=lines.map(line=>`<polyline class="mw-trajectory" points="${line.points.map(p=>px(p).join(',')).join(' ')}"/><circle class="mw-survey-end" cx="${px(line.points.at(-1))[0]}" cy="${px(line.points.at(-1))[1]}" r="4"/>`).join('');
  if(validPoint(site)){const [x,y]=px(site);geometry+=`<path d="M${x} ${y-6}l6 6 -6 6 -6 -6Z" fill="#7d9186"/><text x="${x+10}" y="${y+4}">Project site</text>`;}
  for(const point of points){const [x,y]=px(point),symbol=settings().symbols?.[point.id]||'Wellhead';geometry+=`<g data-map-point="${esc(point.id)}" transform="translate(${x},${y})"><circle r="18" fill="${point.id===selected?'#e2f2ec':'transparent'}"/>${symbol==='Circle'?'<circle class="mw-point" r="5"/>':symbol==='Square'?'<rect class="mw-point" x="-5" y="-5" width="10" height="10"/>':'<path class="mw-point" d="M0 -10L-6 8H6Z M-4 2H4 M0 -14V-10"/>'}${labels?`<text x="0" y="-23" text-anchor="middle">${esc(point.id)}</text>`:''}</g>`;}
  element.innerHTML=`<svg id="mw-field-svg" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="Field map of confirmed project geometry"><rect width="${width}" height="${height}" fill="#f6faf8"/>${grid}${geometry}${positions.length?`<path d="M45 ${height-46}h80m-80 -4v8m80 -8v8" stroke="#486b5c"/><text x="45" y="${height-56}">${(span*80/(width-90)/1000).toFixed(2)} km · grid distance</text>`:''}</svg>`;
  element.querySelectorAll('[data-map-point]').forEach(g=>g.onclick=()=>{selected=g.dataset.mapPoint;inspector=true;draw();});
 };drawGrid();resizeObserver=new ResizeObserver(drawGrid);resizeObserver.observe(element);
}
